def g5():
    o=''
    names=[('Кәсіпорын деңгейі','серверлер, ақпараттық жүйелер'),('Диспетчерлік деңгей','оператор панелі, SCADA'),('Басқару деңгейі','БЛК, қашықтағы кіріс-шығыс'),('Далалық деңгей','датчик, атқарушы механизм')]
    ys=[6,66,126,186]
    for (a,b),y in zip(names,ys):o+=B(4,y,206,38,a+'\n'+b,'bx','t-s')
    for y in ys[:-1]:o+=A(107,y+38,107,y+60,'ln','hd',False,True)
