# ---------- validation ----------
def _clean(t):
    t=re.sub(r'<svg.*?</svg>|<table>.*?</table>','',t,flags=re.S)
    t=re.sub(r'<b>([^<]*?)\.</b>',r'<b>\1</b>',t)
    t=re.sub(r'\b(рус|ағылш|нем|мс)\.','\\1',t)
    return t
for i,txt in enumerate(L):
    txt=_clean(txt)
    for s in re.split(r'(?<=[.!?])\s+',re.sub(r'<[^>]+>',' ',txt)):
        if len(s.split())>25:print('LONG',i,len(s.split()),s[:90])
    for q in re.findall(r'<p[^>]*>(.*?)</p>',txt,flags=re.S):
        if len(re.split(r'(?<=[.!?])\s+',re.sub(r'<[^>]+>','',q).strip()))>4:print('PARA>4',i,q[:60])

